CREATE FUNCTION public.assign_florist_number(p_florist_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_number integer;
begin
  update florists
     set florist_number = coalesce(florist_number, nextval('florist_number_seq'))
   where id = p_florist_id
  returning florist_number into v_number;

  return v_number;
end;
$$;



