CREATE FUNCTION public.bump_magic_token_use(p_token text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update florist_magic_tokens
     set use_count = use_count + 1,
         last_used_at = now()
   where token = p_token;
$$;



