CREATE FUNCTION public.florist_data_issues(p_lifecycle_stage text, p_email text, p_network_id uuid, p_email_shared_count integer, p_email_bounced_at timestamp with time zone, p_lat double precision, p_lng double precision) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_email text := coalesce(regexp_replace(p_email, '^\s+|\s+$', '', 'g'), '');
  v_out text[] := '{}';
begin
  if coalesce(p_lifecycle_stage, '') in ('production', 'onboarding') then
    return v_out;
  end if;

  if v_email = '' then
    v_out := v_out || 'missing-email'::text;
  elsif v_email !~ '^[A-Za-z0-9_%+''-]+(\.[A-Za-z0-9_%+''-]+)*@[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*\.([A-Za-z]{2,63}|xn--[A-Za-z0-9-]+)$' then
    v_out := v_out || 'bad-email'::text;
  elsif p_network_id is not null or coalesce(p_email_shared_count, 1) > 1 then
    v_out := v_out || 'shared-email'::text;
  elsif p_email_bounced_at is not null then
    v_out := v_out || 'bad-email'::text;
  end if;

  if p_lat is null or p_lng is null then
    v_out := v_out || 'missing-location'::text;
  end if;

  return v_out;
end;
$_$;



--

--

COMMENT ON FUNCTION public.florist_data_issues(p_lifecycle_stage text, p_email text, p_network_id uuid, p_email_shared_count integer, p_email_bounced_at timestamp with time zone, p_lat double precision, p_lng double precision) IS 'The missing-details codes for a florist row. SQL twin of dashboard/lib/match.ts::contactGaps. Email shape = SENDABLE_EMAIL_SHAPE (ASCII only) since 2026-09-18.';


