CREATE FUNCTION public.florists_data_issues_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.data_issues := public.florist_data_issues(
    new.lifecycle_stage, new.email, new.network_id, new.email_shared_count,
    new.email_bounced_at, new.lat, new.lng
  );
  return new;
end;
$$;



