CREATE FUNCTION public.record_candidates_left_out(p_order_id uuid, p_florists jsonb, p_actor text DEFAULT 'system'::text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_list jsonb;
  v_n integer;
begin
  if p_order_id is null or p_florists is null or jsonb_typeof(p_florists) <> 'array'
     or jsonb_array_length(p_florists) = 0 then
    return 0;
  end if;

  with input as (
    select (e->>'floristId')::uuid as florist_id,
           nullif(e->>'distanceKm', '')::numeric as distance_km,
           coalesce(
             array(select jsonb_array_elements_text(case when jsonb_typeof(e->'issues') = 'array' then e->'issues' else '[]'::jsonb end)),
             '{}'
           ) as issues,
           t.ord
      from jsonb_array_elements(p_florists) with ordinality as t(e, ord)
     where e ? 'floristId'
  ),
  upd as (
    update florists f
       set data_issues_seen_at = now(),
           data_issues_skip_count = f.data_issues_skip_count
             + case when f.data_issues_last_order_id is distinct from p_order_id then 1 else 0 end,
           data_issues_last_order_id = p_order_id
      from input i
     where f.id = i.florist_id
    returning f.id, f.name, f.data_issues, f.email_shared_count
  )
  select jsonb_agg(
           jsonb_build_object(
             'floristId', u.id,
             'name', u.name,
             'distanceKm', case when i.distance_km is null then null else round(i.distance_km, 1) end,
             'issues', to_jsonb(case when cardinality(u.data_issues) > 0 then u.data_issues else i.issues end),
             'emailSharedCount', u.email_shared_count
           ) order by i.ord),
         count(*)
    into v_list, v_n
    from upd u
    join input i on i.florist_id = u.id;

  if coalesce(v_n, 0) = 0 then
    return 0;
  end if;

  insert into order_events (order_id, type, payload, actor)
  values (p_order_id, 'candidates_left_out', jsonb_build_object('florists', v_list), coalesce(p_actor, 'system'));

  return v_n;
end;
$$;



--

--

COMMENT ON FUNCTION public.record_candidates_left_out(p_order_id uuid, p_florists jsonb, p_actor text) IS 'Records the shops the missing-details rule kept off one match run: bumps each shop''s data_issues_* tally and writes one candidates_left_out order event. Service role only.';


--

--

CREATE FUNCTION public.run_readonly_stats_query(q text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform set_config('statement_timeout', '5000', true);
  perform set_config('transaction_read_only', 'on', true);

  return stats_sandbox.fetch_capped(q);
exception
  when others then
    -- Returned rather than raised so the chat model sees the error text and can
    -- correct its own query. A blocked table surfaces here as e.g.
    -- "permission denied for table florist_magic_tokens".
    return jsonb_build_object('error', sqlerrm);
end;
$$;



--

--

CREATE FUNCTION stats_sandbox.fetch_capped(q text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cur      refcursor;
  rec      record;
  fetched  jsonb[] := '{}';
  n        integer := 0;
  -- Real wall-clock budget. See the note on statement_timeout in
  -- run_readonly_stats_query below for why this is here and not left to that.
  deadline timestamptz := clock_timestamp() + interval '5 seconds';
begin
  open cur for execute q;
  loop
    fetch cur into rec;
    exit when not found;
    fetched := fetched || to_jsonb(rec);
    n := n + 1;
    exit when n >= 500;
    if clock_timestamp() > deadline then
      -- Raise rather than return what we have: a silently truncated result set
      -- is a wrong answer the chat would then narrate as fact.
      raise exception 'stats query exceeded its 5s row-fetch budget';
    end if;
  end loop;
  close cur;

  return coalesce(to_jsonb(fetched), '[]'::jsonb);
end;
$$;



