    offer_window_far_min integer DEFAULT 120 NOT NULL,
    offer_window_nodate_min integer DEFAULT 60 NOT NULL,
    late_accept_buffer_hours integer DEFAULT 2 NOT NULL,
    reconcile_all_mode text,
    reconcile_all_after_created_at timestamp with time zone,
    reconcile_all_after_id uuid,
    reconcile_all_stats jsonb,
    stats_chat_model text DEFAULT 'anthropic/claude-sonnet-5'::text NOT NULL,
    test_shop_matching text DEFAULT 'exclude'::text NOT NULL,
    match_ring_edges_km numeric[] DEFAULT '{5,10,20}'::numeric[] NOT NULL,
    match_weight_distance numeric DEFAULT 0.25 NOT NULL,
    match_weight_onboarded numeric DEFAULT 3.0 NOT NULL,
    match_weight_emailable numeric DEFAULT 1.5 NOT NULL,
    match_weight_quality numeric DEFAULT 1.0 NOT NULL,
    match_weight_source numeric DEFAULT 1.2 NOT NULL,
