    match_require_trust_tier boolean DEFAULT true NOT NULL,
    cold_offer_enabled boolean DEFAULT false NOT NULL,
    cold_offer_max_payout_eur numeric DEFAULT 120 NOT NULL,
    cold_offer_auto_payout_cap_eur numeric DEFAULT 90 NOT NULL,
    cold_offer_default_radius_km numeric DEFAULT 12 NOT NULL,
    message_voice jsonb DEFAULT '{}'::jsonb NOT NULL,
    sequence_enabled boolean DEFAULT false NOT NULL,
    sequence_min_gap_hours integer DEFAULT 48 NOT NULL,
    sequence_daily_send_cap integer DEFAULT 200,
    voice_enabled boolean DEFAULT false NOT NULL,
    voice_record_audio boolean DEFAULT false NOT NULL,
    voice_transcribe boolean DEFAULT true NOT NULL,
    voice_record_by_country jsonb DEFAULT '{}'::jsonb NOT NULL,
    voice_retention_days integer DEFAULT 90 NOT NULL,
    voice_daily_call_cap integer DEFAULT 50 NOT NULL,
    voice_max_call_seconds integer DEFAULT 300 NOT NULL,
    email_accept_confirm_enabled boolean DEFAULT true NOT NULL,
    sms_accept_confirm_enabled boolean DEFAULT false NOT NULL,
    florist_chat_enabled boolean DEFAULT true NOT NULL,
    cx_email text,
    cx_agent_enabled boolean DEFAULT false NOT NULL,
    cx_agent_min_confidence numeric DEFAULT 0.75 NOT NULL,
    cx_agent_max_auto_turns integer DEFAULT 3 NOT NULL,
    cx_agent_model text DEFAULT 'anthropic/claude-sonnet-5'::text NOT NULL,
    support_agent_enabled boolean DEFAULT false NOT NULL,
    sequence_auto_enrol_scraped boolean DEFAULT false NOT NULL,
    match_max_waves integer DEFAULT 4 NOT NULL,
    cx_reserve_hours integer DEFAULT 2 NOT NULL,
    call_back_gap_rush_min integer DEFAULT 10 NOT NULL,
    call_back_gap_sameday_min integer DEFAULT 20 NOT NULL,
    call_back_gap_standard_min integer DEFAULT 45 NOT NULL,
    call_back_gap_far_min integer DEFAULT 120 NOT NULL,
    call_back_gap_nodate_min integer DEFAULT 45 NOT NULL,
    operator_view boolean DEFAULT false NOT NULL,
    offer_short_variant_enabled boolean DEFAULT true NOT NULL,
    sequence_auto_enrol_countries text[],
    active_order_countries text[] DEFAULT '{}'::text[] NOT NULL,
    run_all_orders boolean DEFAULT false NOT NULL,
    working_set_radius_km double precision DEFAULT 5 NOT NULL,
    payout_reconcile_last_run_at timestamp with time zone,
    offer_parallel_sends integer DEFAULT 1 NOT NULL,
    payout_blocked_alert_since timestamp with time zone,
    payout_blocked_alert_extra_emails text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT app_settings_reconcile_all_mode_check CHECK (((reconcile_all_mode IS NULL) OR (reconcile_all_mode = ANY (ARRAY['dry'::text, 'apply'::text])))),
    CONSTRAINT app_settings_singleton CHECK ((id = 1)),
    CONSTRAINT app_settings_test_shop_matching_check CHECK ((test_shop_matching = ANY (ARRAY['exclude'::text, 'only'::text]))),
    CONSTRAINT app_settings_workflow_mode_check CHECK ((workflow_mode = ANY (ARRAY['manual'::text, 'semi'::text, 'auto'::text])))
);



