CREATE TABLE public.order_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    florist_id uuid NOT NULL,
    rank integer,
    florist_source text,
    status text DEFAULT 'candidate'::text NOT NULL,
    offer_kind text,
    offer_expires_at timestamp with time zone,
    sla_deadline_at timestamp with time zone,
    decline_reason text,
    decline_detail text,
    draft_subject text,
    draft_body text,
    payout_price numeric,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    opened_at timestamp with time zone,
    accepted_at timestamp with time zone,
    delivered_at timestamp with time zone,
    declined_at timestamp with time zone,
    payout_percent numeric,
    withdrawn_at timestamp with time zone,
    offer_audience text DEFAULT 'network'::text NOT NULL,
    CONSTRAINT order_assignments_offer_audience_check CHECK ((offer_audience = ANY (ARRAY['network'::text, 'cold'::text]))),
    CONSTRAINT order_assignments_offer_kind_check CHECK ((offer_kind = ANY (ARRAY['exclusive'::text, 'race'::text]))),
    CONSTRAINT order_assignments_status_check CHECK ((status = ANY (ARRAY['candidate'::text, 'queued'::text, 'sent'::text, 'opened'::text, 'declined'::text, 'expired'::text, 'accepted'::text, 'reassigned'::text, 'delivered'::text, 'released'::text])))
);



--

--

COMMENT ON COLUMN public.order_assignments.offer_audience IS 'cold = this shop has never joined. lib/coldOffer.ts::coldOfferEligible gates whether we may send one at all; lib/waves.ts treats it as the explicit exception to "auto never auto-offers a non-onboarded florist"; app/api/florist/respond mints a provisional activation on accept instead of demanding one up front.';


