--

CREATE TABLE public.orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    shopify_order_id text,
    order_name text,
    shopify_created_at timestamp with time zone,
    currency text,
    total numeric,
    financial_status text,
    fulfillment_status text,
    locale text,
    city_id uuid,
    buyer_name text,
    buyer_email text,
    buyer_phone text,
    recipient_name text,
    recipient_phone text,
    delivery_address jsonb,
    delivery_area text,
    delivery_lat double precision,
    delivery_lng double precision,
    delivery_at timestamp with time zone,
    delivery_window text,
    occasion text,
    greeting text,
    substitution_policy text,
    status text DEFAULT 'received'::text NOT NULL,
    notes text,
    raw jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    tags text,
    shipping_total numeric,
    worklist_at timestamp with time zone,
    worklist_by text,
    is_demo boolean DEFAULT false NOT NULL,
    demo_source_order_id uuid,
    escalation_reason text,
    list_items_total numeric,
    list_shipping_total numeric,
    list_price_total numeric,
    list_price_note text
);



--

--

COMMENT ON COLUMN public.orders.worklist_at IS 'Non-null = staff explicitly picked this order to be operated on (the working set), unioned with app_settings.active_order_tags. Cleared automatically by the reconcile sweep once the order reaches a terminal state. Removing it never rewinds work already in flight.';


--

--

COMMENT ON COLUMN public.orders.worklist_by IS 'Email of the staff member who added this order to the working set. Audit only — the authoritative trail is the worklist_added / worklist_removed order_events rows.';


--

--

COMMENT ON COLUMN public.orders.is_demo IS 'Staff-created sandbox order (dashboard/lib/testing/demoSandbox.ts) — never a real Shopify order. Always matched only to florists.is_test_shop=true shops, and always paid on the ledger rail (see lib/payout.ts). Excluded from the working set by default (no worklist_at/tag) so real automation never touches it unless staff explicitly run the scenario tooling.';


--

--

COMMENT ON COLUMN public.orders.demo_source_order_id IS 'When a demo order was cloned from a real one, the source orders.id — traceability only, not read by any automation.';


--

--

COMMENT ON COLUMN public.orders.escalation_reason IS 'Why the wave engine escalated: pool_exhausted (every matchable shop in range was tried), wave_ceiling (hit match_max_waves, untried shops may remain), out_of_time (stopped to leave cx_reserve_hours for a human), past_delivery_deadline. Read only while status = ''escalated''. Legacy rows predating this column are null, and older events may carry the retired reason ''candidates_exhausted'', which is treated as pool_exhausted.';


--

--

COMMENT ON COLUMN public.orders.list_items_total IS 'Goods at their pre-discount price (Shopify total_line_items_price, tax-inclusive). Part of list_price_total. See lib/orderPricing.ts.';


--

--

COMMENT ON COLUMN public.orders.list_shipping_total IS 'Sum of shipping_lines[].price — the chosen rate''s price BEFORE any shipping discount (e.g. A Year of Smiles = 12.90 in ES even when discounted to 0). Part of list_price_total.';


--

--

COMMENT ON COLUMN public.orders.list_price_total IS 'Full PVP before customer discounts = list_items_total + list_shipping_total. The florist payout BASIS (lib/orderPricing.ts::payoutBasis). NULL = unknown (reason in list_price_note); payout then falls back to orders.total.';


--

--

COMMENT ON COLUMN public.orders.list_price_note IS 'Why list_price_total is NULL: no_payload | no_line_items_price | no_shipping_lines | shipping_price_missing | taxes_excluded | below_collected_total. NULL when list_price_total is set.';


