CREATE VIEW public.florist_stats WITH (security_invoker='true') AS
 SELECT fl.id AS florist_id,
        CASE
            WHEN ((COALESCE(agg.accepted, (0)::bigint) + COALESCE(agg.declined, (0)::bigint)) = 0) THEN NULL::numeric
            ELSE round(((COALESCE(agg.accepted, (0)::bigint))::numeric / ((COALESCE(agg.accepted, (0)::bigint) + COALESCE(agg.declined, (0)::bigint)))::numeric), 4)
        END AS acceptance_rate,
        CASE
            WHEN (COALESCE(agg.delivered, (0)::bigint) = 0) THEN NULL::numeric
            ELSE round(((COALESCE(agg.on_time, (0)::bigint))::numeric / (agg.delivered)::numeric), 4)
        END AS on_time_rate,
    COALESCE(agg.declined, (0)::bigint) AS decline_count,
    COALESCE(issues.issue_count, (0)::bigint) AS issue_count,
    (COALESCE(agg.accepted, (0)::bigint) + COALESCE(agg.declined, (0)::bigint)) AS sample_size
   FROM ((public.florists fl
     LEFT JOIN ( SELECT oa.florist_id,
            count(*) FILTER (WHERE (oa.status = ANY (ARRAY['accepted'::text, 'delivered'::text]))) AS accepted,
            count(*) FILTER (WHERE (oa.status = 'declined'::text)) AS declined,
            count(*) FILTER (WHERE (oa.status = 'delivered'::text)) AS delivered,
            count(*) FILTER (WHERE ((oa.status = 'delivered'::text) AND (oa.delivered_at IS NOT NULL) AND (o.delivery_at IS NOT NULL) AND (oa.delivered_at <= o.delivery_at))) AS on_time
           FROM (public.order_assignments oa
             LEFT JOIN public.orders o ON ((o.id = oa.order_id)))
          GROUP BY oa.florist_id) agg ON ((agg.florist_id = fl.id)))
     LEFT JOIN ( SELECT oa.florist_id,
            count(*) AS issue_count
           FROM (public.delivery_events de
             JOIN public.order_assignments oa ON ((oa.id = de.assignment_id)))
          WHERE (de.type = 'problem'::text)
          GROUP BY oa.florist_id) issues ON ((issues.florist_id = fl.id)));



--

--

CREATE VIEW public.florist_summary WITH (security_invoker='true') AS
 SELECT (count(*))::integer AS total_florists,
    (count(*) FILTER (WHERE ((COALESCE(email, ''::text) <> ''::text) OR (COALESCE(phone_maps, ''::text) <> ''::text) OR (COALESCE(phone_web, ''::text) <> ''::text))))::integer AS total_reachable,
    (count(*) FILTER (WHERE (is_ecommerce IS TRUE)))::integer AS total_ecommerce,
    (count(*) FILTER (WHERE (drafted_email IS NOT NULL)))::integer AS drafts_ready,
    avg(rating) FILTER (WHERE (rating IS NOT NULL)) AS overall_avg_rating
   FROM public.florists
  WHERE ((deleted_at IS NULL) AND (excluded_at IS NULL));



--

--

COMMENT ON VIEW public.florist_summary IS 'Roster-wide florist aggregates for the staff home Supply-health zone. Replaces shipping the whole roster to the browser. Mirrors lib/stats.ts::computeGlobalSummary.';


