CREATE TABLE public.payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_id uuid,
    leg text NOT NULL,
    amount numeric,
    currency text,
    rail text,
    status text DEFAULT 'pending'::text NOT NULL,
    provider_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    card_status text,
    expires_at timestamp with time zone,
    spent_amount numeric,
    settled_at timestamp with time zone,
    dispute_status text,
    last_txn_id text,
    florist_id uuid,
    CONSTRAINT payouts_leg_check CHECK ((leg = ANY (ARRAY['accept'::text, 'delivery'::text, 'manual'::text]))),
    CONSTRAINT payouts_leg_shape_check CHECK ((((leg = 'manual'::text) AND (assignment_id IS NULL) AND (florist_id IS NOT NULL)) OR ((leg = ANY (ARRAY['accept'::text, 'delivery'::text])) AND (assignment_id IS NOT NULL) AND (florist_id IS NULL)))),
    CONSTRAINT payouts_rail_check CHECK ((rail = ANY (ARRAY['card'::text, 'sepa'::text]))),
    CONSTRAINT payouts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'issued'::text, 'paid'::text, 'failed'::text, 'clawed_back'::text, 'held'::text])))
);



