CREATE VIEW public.florist_workload WITH (security_invoker='true') AS
 WITH asg AS (
         SELECT order_assignments.florist_id,
            count(*) FILTER (WHERE (order_assignments.status = 'accepted'::text)) AS active_orders,
            count(*) FILTER (WHERE (order_assignments.status = ANY (ARRAY['candidate'::text, 'queued'::text, 'sent'::text, 'opened'::text]))) AS pending_offers,
            count(*) FILTER (WHERE (order_assignments.status = ANY (ARRAY['delivered'::text, 'released'::text]))) AS history_count
           FROM public.order_assignments
          GROUP BY order_assignments.florist_id
        ), pay AS (
         SELECT COALESCE(a.florist_id, p.florist_id) AS florist_id,
            sum(p.amount) AS paid_total,
            min(p.currency) AS paid_currency
           FROM (public.payouts p
             LEFT JOIN public.order_assignments a ON ((a.id = p.assignment_id)))
          WHERE (p.status = 'paid'::text)
          GROUP BY COALESCE(a.florist_id, p.florist_id)
        )
 SELECT f.id AS florist_id,
    (COALESCE(asg.active_orders, (0)::bigint))::integer AS active_orders,
    (COALESCE(asg.pending_offers, (0)::bigint))::integer AS pending_offers,
    (COALESCE(asg.history_count, (0)::bigint))::integer AS history_count,
    COALESCE(pay.paid_total, (0)::numeric) AS paid_total,
    pay.paid_currency
   FROM ((public.florists f
     LEFT JOIN asg ON ((asg.florist_id = f.id)))
     LEFT JOIN pay ON ((pay.florist_id = f.id)))
  WHERE ((f.deleted_at IS NULL) AND (f.excluded_at IS NULL) AND ((COALESCE(asg.active_orders, (0)::bigint) > 0) OR (COALESCE(asg.pending_offers, (0)::bigint) > 0) OR (COALESCE(asg.history_count, (0)::bigint) > 0) OR (COALESCE(pay.paid_total, (0)::numeric) <> (0)::numeric)));



--

--

COMMENT ON VIEW public.florist_workload IS 'Per-florist operational counters for the /florists directory. Replaces a full-table read of order_assignments + payouts reduced in JS. Status buckets mirror app/(staff)/florists/page.tsx.';


