CREATE TABLE public.ingest_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    country text NOT NULL,
    city text NOT NULL,
    radius_km double precision,
    limit_per_keyword integer,
    keywords jsonb,
    language text,
    reset_existing boolean DEFAULT false NOT NULL,
    status text NOT NULL,
    last_line text,
    log text,
    error text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    input_tokens bigint,
    output_tokens bigint,
    llm_calls integer,
    llm_cost_usd numeric,
    llm_cost_by_type jsonb,
    apify_cost_usd numeric,
    florist_count integer,
    mode text DEFAULT 'city'::text NOT NULL,
    region text DEFAULT ''::text NOT NULL,
    near_lat double precision,
    near_lng double precision,
    CONSTRAINT ingest_jobs_mode_check CHECK ((mode = ANY (ARRAY['city'::text, 'repair'::text]))),
    CONSTRAINT ingest_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text])))
);



--

--

COMMENT ON COLUMN public.ingest_jobs.mode IS 'city = full ingest (geocode -> keywords -> Apify -> relevance -> enrich). repair = re-enrich rows already in `florists` for this city, no Apify run and nothing billed there; see ingest-worker/src/workflow.ts and docs/superpowers/specs/2026-08-11-enrichment-repair-mode-design.md.';


--

--

COMMENT ON COLUMN public.ingest_jobs.region IS 'Administrative region/state hint (e.g. "Balears"), appended to the Nominatim query to disambiguate same-named cities, and part of the idempotency key alongside (country, city). '''' = no hint available.';


--

--

COMMENT ON COLUMN public.ingest_jobs.near_lat IS 'Reference latitude the geocoded city center is sanity-checked against (see ingest/geocode.py::MAX_GEOCODE_DRIFT_KM). Null = no check performed.';


--

--

COMMENT ON COLUMN public.ingest_jobs.near_lng IS 'Reference longitude paired with near_lat.';


