    resolved_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    florist_unread boolean DEFAULT false NOT NULL,
    cx_unread boolean DEFAULT false NOT NULL,
    CONSTRAINT order_issues_resolution_action_check CHECK ((resolution_action = ANY (ARRAY['substitute'::text, 'reassign'::text, 'redeliver'::text, 'clawback'::text, 'cancel'::text, 'dismiss'::text]))),
    CONSTRAINT order_issues_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text]))),
    CONSTRAINT order_issues_type_check CHECK ((type = ANY (ARRAY['missing_ingredient'::text, 'wrong_address'::text, 'out_of_range'::text, 'recipient_unavailable'::text, 'damaged_wrong_recipient'::text, 'other'::text, 'awaiting_photo'::text])))
);



--

--

COMMENT ON CONSTRAINT order_issues_type_check ON public.order_issues IS 'Issue types. All florist-raised except awaiting_photo, which CX raises to chase a shop that accepted and then went quiet.';


