    signature_note text,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);



--

--

COMMENT ON TABLE public.outreach_personas IS 'The named human persona that signs every outreach follow-up, one active row per locale. Read at send time by lib/personas.ts::resolvePersona (pure; falls back to the EN persona so a market without one never renders a blank signature) and by lib/sequences/tick.ts for any step whose `from` is "persona".';


--

--

COMMENT ON COLUMN public.outreach_personas.reply_to IS 'A REAL inbox on the Resend inbound domain — replies land in app/api/webhooks/resend-inbound and are answered by lib/cxAgent.ts or escalated to a human. Not decorative: a persona signature over a non-existent address turns every interested reply into a bounce.';


--

--

COMMENT ON COLUMN public.outreach_personas.phone_e164 IS 'The local number this persona answers on. Null until the deferred voice phase; when set it matches a phone_numbers row and is what the ElevenLabs agent answers as.';


