    purchased_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    CONSTRAINT phone_numbers_status_check CHECK ((status = ANY (ARRAY['available'::text, 'assigned'::text, 'releasing'::text, 'released'::text])))
);



--

--

COMMENT ON TABLE public.phone_numbers IS 'Telnyx DID inventory. DEFERRED: created so the seams are real, unused until the voice phase. The city -> number mapping here is the single lookup both call directions read.';


