CREATE TABLE public.sequence_custom_steps (
    step_key text NOT NULL,
    sequence_id text NOT NULL,
    source_step_key text NOT NULL,
    after_step_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text
);



--

--

COMMENT ON TABLE public.sequence_custom_steps IS 'A duplicated funnel touch, created from /flows. Injected into the sequence by the pure lib/flows/customSteps.ts::applyCustomSteps, which also raises that sequence''s touch caps so an added step is not created and then silently capped. Its wait and its on/off switch live in sequence_step_timing under the same step_key; its words live in message_overrides under email.<ns>.<step_key>.<leaf>.';


--

--

CREATE TABLE public.sequence_enrolments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    florist_id uuid NOT NULL,
    sequence_id text NOT NULL,
    order_id uuid,
    assignment_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    track text DEFAULT 'cold'::text NOT NULL,
    step_index integer DEFAULT 0 NOT NULL,
    next_action_at timestamp with time zone DEFAULT now() NOT NULL,
    engaged_at timestamp with time zone,
    last_touch_at timestamp with time zone,
    touches_email integer DEFAULT 0 NOT NULL,
    touches_sms integer DEFAULT 0 NOT NULL,
    paused_by uuid,
    stop_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_at timestamp with time zone,
    CONSTRAINT sequence_enrolments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'converted'::text, 'stopped'::text, 'exhausted'::text]))),
    CONSTRAINT sequence_enrolments_track_check CHECK ((track = ANY (ARRAY['cold'::text, 'reengage'::text])))
);



--

--

COMMENT ON TABLE public.sequence_enrolments IS 'One florist''s run through one outreach funnel. Advanced by lib/sequences/tick.ts on the per-minute cron, which delegates every decision to the pure lib/sequences/schedule.ts::nextDecision. The funnel definition itself is code (lib/sequences/definitions.ts), not rows.';


--

--

COMMENT ON COLUMN public.sequence_enrolments.next_action_at IS 'When the tick should next look at this row. Advanced under a CAS on this exact value (see lib/sequences/tick.ts) so two overlapping ticks cannot both send the same touch — the same discipline lib/waves.ts uses on offer_expires_at.';


--

--

COMMENT ON COLUMN public.sequence_enrolments.engaged_at IS 'First click on any link, any channel. Written by lib/sequences/engagement.ts::recordEngagement from the Resend webhook and the short-link redirect — NOT from the tick. It has to be prompt: a florist who clicks at 08:59 must not get the "just following up" email the 09:00 tick was about to send. Idempotent, because corporate link scanners click every URL in an email.';


--

--

COMMENT ON COLUMN public.sequence_enrolments.paused_by IS 'An order offer PREEMPTS recruiting. Offering an order pauses that florist''s recruiting run and points this at the preempting enrolment; if the order goes elsewhere, the recruiting run resumes at the same step_index rather than restarting.';


--

--

COMMENT ON COLUMN public.sequence_enrolments.stop_reason IS 'Why the run ended: joined | opted_out | replied | exhausted | cap_cold | cap_email | bounced | staff. ''exhausted'' is the normal end — the prospect passes to long-term nurture rather than being marked a failure.';


--

--

COMMENT ON COLUMN public.sequence_enrolments.opened_at IS 'First genuine (openQuality-passing) email open on this run, written CAS-guarded by the Resend webhook. Mirrors engaged_at. NULL means no open was RECORDED, which is not the same as "did not open" — with no provider feedback at all the scheduler resolves OpenState to `unknown` and refuses to gate on it.';


--

--

CREATE TABLE public.sequence_step_timing (
    sequence_id text NOT NULL,
    step_key text NOT NULL,
    days numeric(7,3),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text,
    enabled boolean DEFAULT true NOT NULL,
    CONSTRAINT sequence_step_timing_days_check CHECK (((days IS NULL) OR ((days >= (0)::numeric) AND (days <= (90)::numeric))))
);



--

--

COMMENT ON TABLE public.sequence_step_timing IS 'Staff-editable wait time per funnel step, set from /flows. Overrides SequenceStep.days in lib/sequences/definitions.ts; a missing row means the code default. Applied in lib/flows/timing.ts::applyStepTiming.';


--

--

COMMENT ON COLUMN public.sequence_step_timing.days IS 'Days after the step''s anchor, or NULL for the built-in wait in lib/sequences/definitions.ts. NULL is NOT zero — zero means send immediately.';


--

--

COMMENT ON COLUMN public.sequence_step_timing.enabled IS 'false = the sequence engine SKIPS this step and moves to the next one (lib/sequences/schedule.ts::nextDecision). Default true; a step with no row is on, with its built-in wait. Set from /flows.';


--

--

CREATE TABLE public.short_links (
    code text NOT NULL,
    target_url text NOT NULL,
    kind text NOT NULL,
    florist_id uuid,
    assignment_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    hit_count integer DEFAULT 0 NOT NULL,
    first_hit_at timestamp with time zone,
    last_hit_at timestamp with time zone
);



--

--

COMMENT ON TABLE public.short_links IS 'Code -> URL for links embedded in outbound SMS. The code IS a credential (it fronts a magic-link login), so it is generated from crypto randomness at 10 base62 chars (~59 bits) — see dashboard/lib/shortLink.ts. No expires_at on purpose: the TARGET owns its lifetime (a magic token still expires in 30 days and falls back to sign-in), and a short link expiring before its target would break a working link.';


--

--

COMMENT ON COLUMN public.short_links.hit_count IS 'Redeem count. Deliberately the only click data kept — no IP, user-agent or per-click rows — so this needs no retention policy. Distinguishes "florist never opened it" from "opened and ignored".';


--

--

CREATE TABLE public.sms_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
