    error_detail text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    raw jsonb NOT NULL,
    CONSTRAINT sms_events_event_type_check CHECK ((event_type = ANY (ARRAY['queued'::text, 'sending'::text, 'sent'::text, 'delivered'::text, 'sending_failed'::text, 'delivery_failed'::text, 'delivery_unconfirmed'::text])))
);



--

--

COMMENT ON TABLE public.sms_events IS 'One row per Telnyx message.finalized/message.sent webhook, linked back to the communications row it is about. Populated by app/api/webhooks/telnyx/route.ts.';


