CREATE TABLE public.voice_calls (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    florist_id uuid,
    phone_number_id uuid,
    direction text NOT NULL,
    from_e164 text,
    to_e164 text,
    telnyx_call_control_id text,
    elevenlabs_agent_id text,
    elevenlabs_conversation_id text,
    status text,
    duration_seconds integer,
    transcript jsonb,
    summary text,
    outcome text,
    disclosure_played boolean DEFAULT true NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    notice_text text,
    notice_played boolean DEFAULT false NOT NULL,
    recording_url text,
    retain_until timestamp with time zone,
    purged_at timestamp with time zone,
    CONSTRAINT voice_calls_direction_check CHECK ((direction = ANY (ARRAY['in'::text, 'out'::text])))
);



--

--

COMMENT ON COLUMN public.voice_calls.disclosure_played IS 'Whether the agent actually played the "this is an automated assistant, I can put you through to a person" opener. Recorded per call, not assumed from configuration.';


--

--

COMMENT ON COLUMN public.voice_calls.notice_played IS 'Whether the caller heard the AI + recording notice before recording began. A recording with this false is a compliance incident, not a data problem — lib/voice/recordingPolicy.ts is written so it cannot happen, and this column is how that is proved afterwards.';


--

--

COMMENT ON COLUMN public.voice_calls.retain_until IS 'Hard deletion deadline for recording_url + transcript. Stamped at call time from the then-current retention setting, so shortening the policy later shortens the life of NEW recordings without retroactively extending old ones.';


--

--

COMMENT ON COLUMN public.voice_calls.purged_at IS 'When the audio and transcript were actually deleted. The call row survives with its outcome and duration — those are business records, not personal content — so statistics stay honest after a purge.';


