--

CREATE POLICY "florist reads own assignments" ON public.order_assignments FOR SELECT TO authenticated USING ((florist_id = public.current_florist_id()));


--

--

CREATE POLICY "florist reads own communications" ON public.communications FOR SELECT TO authenticated USING (((florist_id = ( SELECT public.current_florist_id() AS current_florist_id)) AND (audience = 'florist'::text)));


--

--

CREATE POLICY "florist reads own conversation_messages" ON public.conversation_messages FOR SELECT TO authenticated USING (((status = ANY (ARRAY['received'::text, 'sent'::text])) AND (conversation_id IN ( SELECT conversations.id
   FROM public.conversations
  WHERE (conversations.florist_id = public.current_florist_id())))));


--

--

CREATE POLICY "florist reads own conversations" ON public.conversations FOR SELECT TO authenticated USING ((florist_id = public.current_florist_id()));


--

--

CREATE POLICY "florist reads own delivery_events" ON public.delivery_events FOR SELECT TO authenticated USING ((assignment_id IN ( SELECT order_assignments.id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own florist_messages" ON public.florist_messages FOR SELECT TO authenticated USING ((florist_id = public.current_florist_id()));


--

--

CREATE POLICY "florist reads own invites" ON public.florist_invites FOR SELECT TO authenticated USING ((florist_id = public.current_florist_id()));


--

--

CREATE POLICY "florist reads own issue_messages" ON public.issue_messages FOR SELECT TO authenticated USING ((assignment_id IN ( SELECT order_assignments.id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own line items" ON public.order_line_items FOR SELECT TO authenticated USING ((order_id IN ( SELECT order_assignments.order_id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own mapping" ON public.florist_users FOR SELECT TO authenticated USING ((user_id = auth.uid()));


--

--

CREATE POLICY "florist reads own order_issues" ON public.order_issues FOR SELECT TO authenticated USING ((assignment_id IN ( SELECT order_assignments.id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own orders" ON public.orders FOR SELECT TO authenticated USING ((id IN ( SELECT order_assignments.order_id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own payouts" ON public.payouts FOR SELECT TO authenticated USING ((assignment_id IN ( SELECT order_assignments.id
   FROM public.order_assignments
  WHERE (order_assignments.florist_id = public.current_florist_id()))));


--

--

CREATE POLICY "florist reads own push subs" ON public.push_subscriptions FOR SELECT TO authenticated USING ((florist_id = public.current_florist_id()));


